import{_ as t,o as i,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-1-push-notification/report3_spec_en.md","filePath":"feature/admin-management/3-10-1-push-notification/report3_spec_en.md"}'),s={name:"feature/admin-management/3-10-1-push-notification/report3_spec_en.md"};function o(r,e,l,c,d,p){return i(),n("div",null,[...e[0]||(e[0]=[a("<p><strong>3.10.1 Push Notification</strong></p><p><strong>Function Trigger</strong></p><p>Begins when an Administrator (ADMIN) navigates to /admin/notifications and clicks the &quot;Compose Notification&quot; button.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. System administrator with full administrative authority to issue and broadcast notifications across the platform.</li><li><strong>Purpose</strong>: Compose and send system notifications by EMAIL, immediately or on a schedule. In-app and FCM delivery are deferred.</li><li><strong>Interface</strong>: System Notification Screen (SCR-ADM-01), with email composition, audience criteria, draft/schedule controls and delivery history.</li><li><strong>Data Processing</strong>: Verify ADMIN, validate message and audience criteria, persist draft/schedule, and resolve recipients at actual send time. Dispatch through the email service and record delivery outcomes and audit events; protect dispatch against concurrent edit/cancel and duplicate retries.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — System Push Notification Screen (SCR-ADM-01, full-width admin form layout):</p><ul><li>Left/Header: Sidebar Admin Navigation; Top Header displaying page title &quot;System Notification Management&quot; and button &quot;Compose New Notification&quot;.</li><li>Center: Title (5–200 characters), body (10–5,000), type (System/Maintenance/Update/Promotion), audience ALL/BY_PLAN/BY_ROLE, catalog plan selector or ADMIN/USER selector, optional action URL, schedule time and timezone. Show estimated recipients separately from final recipients.</li><li>Buttons: Send Now, Schedule Delivery, Save Draft; edit/cancel only DRAFT or SCHEDULED. Sent messages cannot be recalled.</li><li>Footer: History and pagination; status DRAFT, SCHEDULED, SENT, FAILED or CANCELLED; delivery counts and failure details. SENT records completed dispatch, not proof that recipients read the email.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: title (5–200), content (10–5,000), type (SYSTEM, MAINTENANCE, UPDATE, PROMOTION), targetType (ALL, BY_PLAN, BY_ROLE).</li><li><strong>Input optional</strong>: targetPlans (catalog IDs, required for BY_PLAN), targetRoles (ADMIN/USER, required for BY_ROLE), scheduledAt (ISO timestamp with offset), actionUrl.</li><li><strong>System data</strong>: notificationId, senderId, channel=EMAIL, status (DRAFT, SCHEDULED, SENT, FAILED, CANCELLED), createdAt, sentAt, recipientCount, deliveryResults.</li><li><strong>Output</strong>: Created notification record payload with HTTP status code 201 Created.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-35</strong>: All broadcast operations require authenticated ADMIN authority.</li><li><strong>BR-57</strong>: This phase sends EMAIL only; title is 5–200 and content 10–5,000 characters. In-app and FCM are outside this phase.</li><li><strong>BR-65</strong>: Resolve recipients at actual send time using the saved audience criteria. Preview counts are estimates; an empty audience completes with recipientCount=0.</li><li><strong>BR-82</strong>: BY_ROLE accepts ADMIN/USER only; BY_PLAN uses the existing subscription catalog. Agency membership roles are not system roles.</li><li><strong>BR-57</strong>: Only DRAFT and SCHEDULED may be edited/cancelled. Cancel sets CANCELLED and prevents dispatch. Sending locks the revision; sent email cannot be recalled. Record partial failures and retry only unsent recipients.</li><li><strong>BR-16</strong>: Audit creation, editing, scheduling, cancellation and dispatch with actor, criteria, timestamps and final recipient counts.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>User does not possess ADMIN role permissions → Display: MSG39</li><li>Notification title or content is empty → Display: MSG02</li><li>Notification title or content length exceeds allowed boundaries → Display: MSG03</li><li>Scheduled delivery timestamp is invalid or set in the past → Display: MSG45</li><li>Notification dispatched or scheduled successfully → Display: MSG144</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Admin opens SCR-ADM-01 and composes an email notification.</li><li>Admin selects audience criteria and saves a draft, sends now or schedules a future timestamp.</li><li>System validates content, catalog values and ADMIN authority; persists the chosen action and audit event.</li><li>Admin may edit/cancel while DRAFT or SCHEDULED; worker verifies the current revision before sending.</li><li>At actual dispatch, resolve recipients using current roles/plans and send email.</li><li>Record delivery results, final recipient count, status and audit; refresh history.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>1.a1: Missing ADMIN authority → MSG39; invalid mandatory fields → MSG02/MSG03.</li><li>2.a1: Schedule in the past or missing audience criteria → validation error; no dispatch.</li><li>4.a1: Edit/cancel after dispatch started or on SENT/FAILED/CANCELLED → conflict; do not recall sent email.</li><li>5.a1: Email outage/partial failure → retain delivery results and allow safe delivery retry without resending successful recipients.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Notification content, audience criteria, lifecycle status and delivery outcomes are persisted.</li><li>Only eligible recipients at dispatch time receive EMAIL; cancelled jobs do not dispatch.</li><li>Every administrative change and dispatch has an immutable audit trail.</li></ul>",14)])])}const m=t(s,[["render",o]]);export{g as __pageData,m as default};
